      const p = new THREE.Group();
      const body = new THREE.Mesh(new THREE.CapsuleGeometry(.25,.65,3,6), new THREE.MeshStandardMaterial({ color:[0x1a2223,0x242b2c,0x30282a][i%3], roughness:1 }));
