  }
  if (boss === 'mayor') {
    const sash = new THREE.Mesh(new THREE.BoxGeometry(.1,.76,.03), new THREE.MeshStandardMaterial({ color:0xff4338, roughness:.5, emissive:0x3a0807 })); sash.position.set(0,1.16,.24); sash.rotation.z = .36; g.add(sash);
  }
  if (boss === 'mirror') {
    const mat = new THREE.MeshStandardMaterial({ color:0xa9b8b6, metalness:.9, roughness:.12, emissive:0x0d2524 });
    g.traverse(o => { if (o.isMesh) { o.material = mat; } });
    const eyes = new THREE.MeshBasicMaterial({ color:0x7fe3d2, toneMapped:false });
    const e1 = new THREE.Mesh(new THREE.SphereGeometry(.03,5,4), eyes); e1.position.set(-.065,1.72,.19); g.add(e1);
    const e2 = new THREE.Mesh(new THREE.SphereGeometry(.03,5,4), eyes); e2.position.set(.065,1.72,.19); g.add(e2);
  }
  if (boss === 'future') {
    const coat = new THREE.Mesh(new THREE.CylinderGeometry(.35,.47,1.3,8), new THREE.MeshStandardMaterial({ color:0x0d1213, roughness:.6, metalness:.3 })); coat.position.y = 1.0; g.add(coat);
    const glow = new THREE.PointLight(0xff4338, 3, 6, 2); glow.position.set(0,1.75,.2); g.add(glow);
  }
  if (def.id === 'dax') {
    const chain = new THREE.Mesh(new THREE.TorusGeometry(.09,.012,4,10), new THREE.MeshStandardMaterial({ color:0xd0b36c, metalness:.9, roughness:.25 })); chain.position.set(0,1.48,.22); g.add(chain);
  }
  if (def.id === 'sasha') {
    const guitar = new THREE.Group();
    const body = new THREE.Mesh(new THREE.CylinderGeometry(.22,.28,.08,10), new THREE.MeshStandardMaterial({ color:0x4b2c26 })); body.rotation.x = Math.PI/2; guitar.add(body);
    const neck = new THREE.Mesh(new THREE.BoxGeometry(.07,.6,.05), new THREE.MeshStandardMaterial({ color:0x2d2018 })); neck.position.y = .37; guitar.add(neck);
    guitar.position.set(.44,.9,-.1); guitar.rotation.z = -.35; g.add(guitar);
  }
  if (def.id === 'nadia') {
    const book = new THREE.Mesh(new THREE.BoxGeometry(.3,.4,.07), new THREE.MeshStandardMaterial({ color:0x7a4c3c })); book.position.set(.35,1.0,.15); book.rotation.z = .2; g.add(book);
  }

  const shadow = new THREE.Mesh(new THREE.PlaneGeometry(1.25, .7), new THREE.MeshBasicMaterial({ map:shadowTex, transparent:true, depthWrite:false, opacity:.6 }));
  shadow.rotation.x = -Math.PI / 2; shadow.position.y = .02; g.add(shadow);

  const label = new THREE.Sprite(new THREE.SpriteMaterial({ map:nameTexture(def.name, def.tag || def.role, p.accent), transparent:true, depthWrite:false, opacity:.9 }));
  label.position.y = 2.22; label.scale.set(3.2, .8, 1); g.add(label);

  g.scale.setScalar((def.height || 1.72) / 1.72);
  return { group:g, torso, head, leftArm, rightArm, leftLeg, rightLeg, label, shadow, palette:p };
}

const SCHEDULE_TARGETS = {
  bar:{x:-50,z:36}, club:{x:80,z:70}, lake:{x:300,z:68}, dojo:{x:-158,z:-96},
  home:null, work:null
};

export class NPCSystem {
  constructor(scene, world, state) {
    this.scene = scene;
    this.world = world;
    this.state = state;
    this.npcs = [];
    this.ambient = [];
    this.byId = new Map();
    this.rng = mulberry32(773311);
    this.frozen = new Set();
    this.followers = [];
    this.lastScheduleTick = -1;
    this.clock = 0;
    this.spawned = false;
  }

  build() {
    for (const def of NPCS) {
      const model = makeHuman(def, { boss:def.boss });
      const npc = {
        ...def, model, group:model.group, homePos:def.home, workPos:def.work,
        x:def.work.x, z:def.work.z, targetX:def.work.x, targetZ:def.work.z,
        walkPhase:this.rng()*TAU, speed:.8 + this.rng()*.4, mode:'idle', facing:0,
        visible:true, lastDist:999, talkCount:0, fightCount:0
      };
      model.group.position.set(npc.x, 0, npc.z);
      this.scene.add(model.group);
      this.npcs.push(npc); this.byId.set(npc.id, npc);
    }
    this.buildAmbient(38);
    this.spawned = true;
    this.updateSchedule(true);
  }

  buildAmbient(count) {
    const first = ['Avery','Bex','Cal','Dani','Em','Fin','Gia','Hal','Iris','Jules','Kai','Lena','Milo','Nia','Owen','Pax','Quinn','Rae','Sol','Tess','Uma','Vale','Wes','Xan','Yara','Zed'];
    const last = ['Park','Vale','Moss','Hale','Rook','Fen','Wynn','Cross','Bell','Marsh','North','Sato','Voss','Crane','Reed','Ward','Ash','Kim','Rourke'];
    const roles = ['Pedestrian','Barista','Student','Cyclist','Fisher','Nurse','Clerk','Musician','Cook','Landlord','Tourist','Busker','Dockworker','Teacher','Line Cook'];
    const palettes = [
      {skin:'#b98b6e',shirt:'#3a4b4c',pants:'#22292a',hair:'#231b19',accent:'#7fe3d2'},
      {skin:'#c49b7b',shirt:'#6b4a3a',pants:'#292c2e',hair:'#4a3326',accent:'#ffb35c'},
      {skin:'#8c5e46',shirt:'#4d5d47',pants:'#222627',hair:'#181616',accent:'#86c68f'},
      {skin:'#d3a488',shirt:'#3d3448',pants:'#24202a',hair:'#7e3e4c',accent:'#d9a6ff'},
      {skin:'#a77758',shirt:'#4a4b45',pants:'#252727',hair:'#2b2320',accent:'#e9e4d8'}
    ];
    for (let i = 0; i < count; i++) {
      const district = ['downtown','downtown','downtown','waterfront','fairhaven','campus','residential','industrial','hills'][i % 9];
      const center = this.world.districtMarkers.find(d => d.id === district) || this.world.districtMarkers[0];
      const x = center.x + (this.rng() - .5) * 75, z = center.z + (this.rng() - .5) * 65;
      const def = {
        id:'ambient_' + i, name:first[i % first.length] + ' ' + last[(i * 3) % last.length],
        age:19 + Math.floor(this.rng() * 45), role:roles[i % roles.length], tag:roles[i % roles.length].toUpperCase(),
        district, palette:palettes[i % palettes.length], height:1.58 + this.rng() * .3,
        romanceable:false, fighter:this.rng() < .22, secret:'Maybe a fighter. Maybe just tired.'
      };
      const model = makeHuman(def);
      const npc = {
        ...def, model, group:model.group, x, z, targetX:x, targetZ:z, homePos:{x,z}, workPos:{x,z},
        ambient:true, walkPhase:this.rng()*TAU, speed:.55 + this.rng()*.5, mode:'idle', facing:this.rng()*TAU,
        wanderTimer:this.rng()*5, visible:true
      };
      model.group.position.set(x, 0, z);
      this.scene.add(model.group);
      this.ambient.push(npc); this.byId.set(npc.id, npc);
    }
  }

  targetFor(npc) {
    const h = (this.state.time.minutes || 480) / 60;
    if (npc.ambient) return { x:npc.homePos.x + Math.sin(this.clock * .2 + npc.walkPhase) * 8, z:npc.homePos.z + Math.cos(this.clock * .17 + npc.walkPhase) * 8 };
    const sched = npc.schedule || [];
    let target = 'work';
    for (const s of sched) if (h >= s.h) target = s.at;
    if (target === 'home') return npc.homePos;
    if (target === 'work') return npc.workPos;
    if (SCHEDULE_TARGETS[target]) return SCHEDULE_TARGETS[target];
    return npc.workPos;
  }

  updateSchedule(force = false) {
    const tick = Math.floor((this.state.time.minutes || 0) / 5);
    if (!force && tick === this.lastScheduleTick) return;
    this.lastScheduleTick = tick;
    for (const npc of this.npcs) {
      const t = this.targetFor(npc);
      npc.targetX = t.x; npc.targetZ = t.z;
    }
  }

  nearest(x, z, maxDist = 3.8) {
    let best = null, bd = maxDist;
    for (const npc of [...this.npcs, ...this.ambient]) {
      if (this.frozen.has(npc.id)) continue;
      const d = Math.hypot(npc.x - x, npc.z - z);
      if (d < bd) { bd = d; best = npc; }
    }
    return best;
  }

  byIdOrNull(id) { return this.byId.get(id) || null; }

  setFrozen(npcOrId, on = true) {
    const npc = typeof npcOrId === 'string' ? this.byId.get(npcOrId) : npcOrId;
    if (!npc) return;
    if (on) this.frozen.add(npc.id); else this.frozen.delete(npc.id);
    npc.frozen = on;
  }

  startFollow(npc, duration = 45) {
    if (!npc) return;
    npc.followUntil = this.clock + duration;
    this.followers.push(npc);
  }

  allActive() { return [...this.npcs, ...this.ambient]; }

  update(dt, playerPos, elapsed) {
    this.clock = elapsed;
    this.updateSchedule();
    const p = playerPos;
    for (const npc of [...this.npcs, ...this.ambient]) {
      if (this.frozen.has(npc.id)) {
        this.animateIdle(npc, dt, true);
        continue;
      }
      let tx = npc.targetX, tz = npc.targetZ;
      if (npc.followUntil && npc.followUntil > this.clock) {
        tx = p.x - 2.2; tz = p.z + 2.2;
      }
      if (npc.ambient) {
        npc.wanderTimer -= dt;
        if (npc.wanderTimer <= 0) {
          npc.wanderTimer = 5 + this.rng() * 9;
          npc.targetX = npc.homePos.x + (this.rng() - .5) * 28;
          npc.targetZ = npc.homePos.z + (this.rng() - .5) * 28;
        }
        tx = npc.targetX; tz = npc.targetZ;
      }
      const dx = tx - npc.x, dz = tz - npc.z;
      const dist = Math.hypot(dx, dz);
      const playerDist = Math.hypot(p.x - npc.x, p.z - npc.z);
      // if far from player and far from schedule, snap to target to keep the city populated
      if (!npc.ambient && dist > 70 && playerDist > 110) {
        npc.x = tx + (this.rng() - .5) * 3; npc.z = tz + (this.rng() - .5) * 3;
        npc.group.position.set(npc.x, 0, npc.z);
      } else if (dist > 1.4) {
        const speed = npc.speed * (npc.followUntil && npc.followUntil > this.clock ? 1.8 : 1);
        const nx = dx / dist, nz = dz / dist;
        const nextX = npc.x + nx * speed * dt, nextZ = npc.z + nz * speed * dt;
        if (!this.world.isBlocked(nextX, nextZ, .3) || playerDist > 40) { npc.x = nextX; npc.z = nextZ; }
        else { npc.targetX += (this.rng() - .5) * 8; npc.targetZ += (this.rng() - .5) * 8; }
        npc.facing = Math.atan2(nx, nz);
        npc.mode = 'walk';
      } else {
        npc.mode = 'idle';
        npc.facing = Math.atan2(p.x - npc.x, p.z - npc.z);
      }
      npc.group.position.set(npc.x, 0, npc.z);
      npc.group.rotation.y = npc.facing;
      this.animateWalk(npc, dt, npc.mode === 'walk');
      const d = Math.hypot(p.x - npc.x, p.z - npc.z);
      npc.model.label.visible = d < 22 && !npc.ambient;
      npc.model.label.material.opacity = clamp(1 - (d - 12) / 10, 0, .95);
      // intoxication at night near bars
      if (!npc.ambient && (this.state.time.minutes > 20 * 60 || this.state.time.minutes < 3 * 60) && npc.id === 'theo') {
        npc.group.rotation.z = Math.sin(elapsed * 1.2) * .02;
      }
    }
    this.followers = this.followers.filter(f => f.followUntil && f.followUntil > this.clock);
  }

  animateWalk(npc, dt, moving) {
    const m = npc.model;
    if (moving) {
      npc.walkPhase += dt * 7;
      const s = Math.sin(npc.walkPhase);
      m.leftLeg.rotation.x = s * .55;
      m.rightLeg.rotation.x = -s * .55;
      m.leftArm.rotation.x = -s * .4;
      m.rightArm.rotation.x = s * .4;
      m.group.position.y = Math.abs(Math.sin(npc.walkPhase)) * .035;
    } else this.animateIdle(npc, dt, false);
  }

  animateIdle(npc, dt, frozen = false) {
    const m = npc.model;
    npc.walkPhase += dt * (frozen ? .2 : 1);
    const s = Math.sin(npc.walkPhase) * (frozen ? .01 : .025);
    m.leftLeg.rotation.x *= .9; m.rightLeg.rotation.x *= .9;
    m.leftArm.rotation.x = s; m.rightArm.rotation.x = -s;
    m.head.rotation.y = frozen ? 0 : Math.sin(npc.walkPhase * .4) * .16;
    m.group.position.y = 0;
  }

  playHit(npc) {
    const m = npc.model;
    npc.hitFlash = .22;
    m.torso.material.emissive = new THREE.Color(0xff2222);
    m.torso.material.emissiveIntensity = .5;
    setTimeout(() => { if (m.torso.material) { m.torso.material.emissive = new THREE.Color(0x000000); m.torso.material.emissiveIntensity = 0; } }, 160);
  }

  faceEachOther(a, b) {
    a.facing = Math.atan2(b.x - a.x, b.z - a.z);
    a.group.rotation.y = a.facing;
  }

  setWeirdness(v) {
    for (const npc of this.npcs) {
      if (v > .5 && npc.id === 'raincoat') npc.group.visible = this.world.weather === 'storm' || v > .75;
    }
  }

  hideAmbient(on) {
    for (const npc of this.ambient) npc.group.visible = !on;
  }

  repeatDialogue() {
    const npc = this.ambient[Math.floor(this.rng() * this.ambient.length)];
    if (!npc) return null;
    npc.repeatUntil = this.clock + 8;
    return npc;
  }
}

import * as THREE from '../vendor/three.module.js';

const clamp = (v,a,b) => Math.max(a, Math.min(b, v));
const lerp = (a,b,t) => a + (b-a)*t;

export class Player {
  constructor(scene, camera, world, state, audio) {
    this.scene = scene;
    this.camera = camera;
    this.world = world;
    this.state = state;
    this.audio = audio;
    this.x = world.spawn.x;
    this.z = world.spawn.z;
    this.y = 0;
    this.yaw = 0;
    this.pitch = -.04;
    this.vx = 0; this.vz = 0; this.vy = 0;
    this.radius = .34;
    this.eyeHeight = 1.68;
    this.crouchHeight = 1.12;
    this.heightBlend = 1;
    this.grounded = true;
    this.crouching = false;
    this.sprinting = false;
    this.speed = 0;
    this.bob = 0;
    this.stepTimer = 0;
    this.input = { forward:0, back:0, left:0, right:0, sprint:false, crouch:false, jump:false };
    this.lookSensitivity = 1;
    this.invert = false;
    this.mode = 'foot';
    this.attackT = 0;
    this.attackType = '';
    this.kickT = 0;
    this.blocking = false;
    this.driving = false;
    this.car = null;
    this.carSpeed = 0;
    this.carAngle = Math.PI / 2;
    this.carSteer = 0;
    this.shake = 0;
    this.cinematic = false;
    this.buildArms();
  }

  buildArms() {
    const group = new THREE.Group();
    const sleeveMat = new THREE.MeshStandardMaterial({ color:0x202a2b, roughness:.82 });
    const skinMat = new THREE.MeshStandardMaterial({ color:0xb98b6e, roughness:.8 });
    const tattooMat = new THREE.MeshStandardMaterial({ color:0x304f4c, roughness:.85 });
    const mkArm = (side) => {
      const arm = new THREE.Group();
      const sleeve = new THREE.Mesh(new THREE.CapsuleGeometry(.075,.33,3,6), sleeveMat);
      sleeve.position.set(0,-.1,-.12); sleeve.rotation.x = Math.PI/2.2; arm.add(sleeve);
      const forearm = new THREE.Mesh(new THREE.CapsuleGeometry(.065,.25,3,6), skinMat);
      forearm.position.set(0,-.07,-.42); forearm.rotation.x = Math.PI/2; arm.add(forearm);
      const fist = new THREE.Mesh(new THREE.SphereGeometry(.1,8,6), skinMat);
      fist.position.set(0,-.03,-.59); arm.add(fist);
      if (side > 0) {
        const ink = new THREE.Mesh(new THREE.TorusGeometry(.065,.008,4,10), tattooMat);
        ink.position.set(0,-.05,-.3); ink.rotation.x = Math.PI/2; arm.add(ink);
      }
      arm.position.set(side * .34, -.32, -.24);
      arm.rotation.set(-.15, side * .08, side * .15);
      group.add(arm);
      return arm;
    };
    this.rightArm = mkArm(1);
    this.leftArm = mkArm(-1);
    const boot = new THREE.Mesh(new THREE.BoxGeometry(.22,.14,.42), new THREE.MeshStandardMaterial({ color:0x1a1d1d, roughness:.8 }));
    boot.position.set(0,-.8,-.65); boot.rotation.x = -.4; boot.visible = false; group.add(boot);
    this.boot = boot;
    group.position.set(0,0,0);
    this.arms = group;
    this.camera.add(group);
    this.armBase = { right:this.rightArm.position.clone(), left:this.leftArm.position.clone() };
  }

  look(dx, dy) {
    if (this.cinematic) return;
    this.yaw -= dx * .0022 * this.lookSensitivity;
    this.pitch -= dy * .0022 * this.lookSensitivity * (this.invert ? -1 : 1);
    this.pitch = clamp(this.pitch, -1.38, 1.2);
    if (this.driving) {
      this.carAngle -= dx * .0012 * this.lookSensitivity;
    }
  }

  moveInput(x, z) {
    this.input.left = x < -.2 ? 1 : 0;
    this.input.right = x > .2 ? 1 : 0;
    this.input.forward = z < -.2 ? 1 : 0;
    this.input.back = z > .2 ? 1 : 0;
  }

  jump() {
    if (this.driving) return;
    if (this.grounded) {
      this.vy = 5.3; this.grounded = false; this.audio?.jump();
    }
  }

  animateAttack(type) {
    this.attackType = type;
    this.attackT = type === 'kick' ? .38 : .3;
    if (type === 'kick') { this.kickT = .38; this.boot.visible = true; }
    if (type === 'special') { this.attackT = .7; }
  }

  enterCar(car) {
    if (this.driving) return;
    this.driving = true;
    this.mode = 'drive';
    this.car = car;
    this.carSpeed = 0;
    this.carAngle = car.rotation.y;
    this.arms.visible = false;
    this.audio?.carStart();
  }

  exitCar() {
    if (!this.driving) return;
    this.driving = false;
    this.mode = 'foot';
    this.arms.visible = true;
    this.x = this.car.position.x + 2.2;
    this.z = this.car.position.z + 1.2;
    if (this.world.isBlocked(this.x, this.z, this.radius)) { this.x = this.car.position.x - 2.2; this.z = this.car.position.z - 1.2; }
    this.y = 0; this.vy = 0;
    this.car = null;
    this.audio?.carStop();
  }

  addShake(amount) { this.shake = Math.min(1.2, this.shake + amount); }

  update(dt, elapsed) {
    if (this.driving) { this.updateDriving(dt, elapsed); return; }
    const s = this.state.player;
    const sprinting = this.input.sprint && s.stamina > 3 && !this.crouching;
    this.sprinting = sprinting;
    this.crouching = this.input.crouch;
    const maxSpeed = this.crouching ? 2.3 : (sprinting ? 7.1 : 4.35);
    let ix = this.input.right - this.input.left;
    let iz = this.input.back - this.input.forward;
    const len = Math.hypot(ix, iz);
    if (len > 1) { ix /= len; iz /= len; }
    const forwardX = -Math.sin(this.yaw), forwardZ = -Math.cos(this.yaw);
    const rightX = Math.cos(this.yaw), rightZ = -Math.sin(this.yaw);
    const wishX = forwardX * -iz + rightX * ix;
    const wishZ = forwardZ * -iz + rightZ * ix;
    const accel = this.grounded ? 34 : 8;
    this.vx = lerp(this.vx, wishX * maxSpeed, clamp(accel * dt, 0, 1));
    this.vz = lerp(this.vz, wishZ * maxSpeed, clamp(accel * dt, 0, 1));
    if (!wishX && !wishZ && this.grounded) { this.vx *= Math.pow(.0008, dt); this.vz *= Math.pow(.0008, dt); }
    this.speed = Math.hypot(this.vx, this.vz);

    // stamina
    if (sprinting && this.speed > .8) {
      s.stamina = Math.max(0, s.stamina - dt * 7);
      s.energy = Math.max(0, s.energy - dt * .04);
    } else {
      s.stamina = Math.min(100, s.stamina + dt * 10);
    }

    const nx = this.x + this.vx * dt;
    const nz = this.z + this.vz * dt;
    if (!this.world.isBlocked(nx, this.z, this.radius)) this.x = nx; else this.vx *= -.05;
    if (!this.world.isBlocked(this.x, nz, this.radius)) this.z = nz; else this.vz *= -.05;

    // jump / gravity
    if (!this.grounded) {
      this.vy -= 14 * dt;
      this.y += this.vy * dt;
      if (this.y <= 0) { this.y = 0; this.vy = 0; this.grounded = true; this.audio?.land(); }
    }
    const targetEye = this.crouching ? this.crouchHeight : this.eyeHeight;
    this.heightBlend = lerp(this.heightBlend, targetEye, dt * 9);
    this.bob += dt * (sprinting ? 12 : 7) * (this.speed > .5 ? 1 : 0);
    const bobY = this.speed > .5 ? Math.sin(this.bob) * (sprinting ? .06 : .032) : 0;
    const bobX = this.speed > .5 ? Math.cos(this.bob * .5) * .012 : 0;
    this.shake = Math.max(0, this.shake - dt * 2.8);
    const shakeX = (Math.random() - .5) * this.shake * .025;
    const shakeY = (Math.random() - .5) * this.shake * .025;
    this.camera.position.set(this.x + bobX + shakeX, this.y + this.heightBlend + bobY + shakeY, this.z);
    this.camera.rotation.order = 'YXZ';
    this.camera.rotation.y = this.yaw;
    this.camera.rotation.x = this.pitch;
    this.camera.rotation.z = this.crouching ? .01 : 0;

    // footsteps
    if (this.speed > .7 && this.grounded) {
      this.stepTimer -= dt * (sprinting ? 1.55 : 1);
      if (this.stepTimer <= 0) {
        this.stepTimer = .42;
        this.audio?.footstep(this.crouching, this.world.weather === 'rain');
      }
    } else this.stepTimer = .15;

    // arms animation
    this.arms.visible = !this.cinematic;
    this.arms.position.y = bobY * .7;
    this.arms.position.x = bobX * .5;
    const idleSway = Math.sin(this.bob * .5) * .012;
    if (this.attackT > 0) {
      this.attackT -= dt;
      const p = 1 - clamp(this.attackT / (this.attackType === 'kick' ? .38 : .3), 0, 1);
      const punch = Math.sin(p * Math.PI);
      if (this.attackType === 'punch') {
        this.rightArm.position.z = this.armBase.right.z - punch * .7;
        this.rightArm.position.x = this.armBase.right.x - punch * .1;
        this.rightArm.rotation.x = -.2 - punch * .5;
        this.leftArm.rotation.x = -.1;
      } else if (this.attackType === 'special') {
        this.rightArm.position.z = this.armBase.right.z - punch * .9;
        this.leftArm.position.z = this.armBase.left.z - punch * .9;
        this.rightArm.rotation.x = this.leftArm.rotation.x = -.3 - punch * .7;
      } else {
        this.boot.visible = true;
        this.boot.position.y = -.8 + punch * .35;
        this.boot.position.z = -.65 - punch * .7;
        this.boot.rotation.x = -.4 + punch * .9;
      }
      if (this.attackT <= 0) {
        this.rightArm.position.copy(this.armBase.right);
        this.leftArm.position.copy(this.armBase.left);
        this.boot.visible = false;
      }
    } else {
      this.rightArm.position.x = this.armBase.right.x;
      this.rightArm.position.z = this.armBase.right.z;
      this.leftArm.position.x = this.armBase.left.x;
      this.leftArm.position.z = this.armBase.left.z;
      if (this.blocking) {
        this.rightArm.position.set(-.15, -.18, -.38); this.leftArm.position.set(.15, -.18, -.38);
        this.rightArm.rotation.x = -.9; this.leftArm.rotation.x = -.9;
      } else {
        this.rightArm.rotation.x = -.15 + idleSway;
        this.leftArm.rotation.x = -.15 - idleSway;
      }
    }
  }

  updateDriving(dt, elapsed) {
    const car = this.car;
    if (!car) { this.driving = false; this.mode = 'foot'; return; }
    const throttle = this.input.forward ? 1 : (this.input.back ? -.55 : 0);
    const steer = (this.input.left ? 1 : 0) - (this.input.right ? 1 : 0);
    this.carSpeed = lerp(this.carSpeed, throttle * 17, dt * 1.1);
    if (!throttle) this.carSpeed *= Math.pow(.3, dt);
    if (this.carSpeed < -.1) this.carSpeed = Math.max(this.carSpeed, -5);
    this.carAngle += steer * dt * (1.2 + Math.abs(this.carSpeed) * .025) * (this.carSpeed >= 0 ? 1 : -1);
    const nx = car.position.x + Math.sin(this.carAngle) * this.carSpeed * dt;
    const nz = car.position.z + Math.cos(this.carAngle) * this.carSpeed * dt;
    if (!this.world.isBlocked(nx, nz, 1.25)) {
      car.position.x = nx; car.position.z = nz;
    } else {
      this.carSpeed *= -.18;
      this.addShake(.3);
      this.audio?.impact(.4);
    }
    car.rotation.y = this.carAngle;
    car.rotation.z = lerp(car.rotation.z, -steer * .02, dt * 4);
    // camera chase
    const camDist = 5.8, camHeight = 2.55;
    const tx = car.position.x - Math.sin(this.carAngle) * camDist;
    const tz = car.position.z - Math.cos(this.carAngle) * camDist;
    this.camera.position.lerp(new THREE.Vector3(tx, camHeight, tz), clamp(dt * 6, 0, 1));
    const lookAt = new THREE.Vector3(car.position.x + Math.sin(this.carAngle) * 4, 1.2, car.position.z + Math.cos(this.carAngle) * 4);
    this.camera.lookAt(lookAt);
    // headlights
    this.shake = Math.max(0, this.shake - dt * 3);
    this.x = car.position.x; this.z = car.position.z; this.y = 0;
    this.audio?.engine(Math.abs(this.carSpeed) / 17);
  }

  teleport(x, z, yaw = 0) {
    this.x = x; this.z = z; this.y = 0; this.yaw = yaw; this.vx = this.vz = this.vy = 0;
    this.camera.position.set(x, this.eyeHeight, z);
    this.camera.rotation.set(this.pitch, yaw, 0);
  }

  getForward() {
    return { x:-Math.sin(this.yaw), z:-Math.cos(this.yaw) };
  }

  distanceTo(x, z) { return Math.hypot(this.x - x, this.z - z); }
}

export class Audio {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.volume = .55;
    this.muted = false;
    this.started = false;
    this.rainGain = null;
    this.humGain = null;
    this.fight = false;
    this.beatTimer = 0;
    this.step = 0;
    this.thunderTimer = 35;
    this.lastEngine = 0;
    this.engineOsc = null;
    this.engineGain = null;
  }

  init() {
    if (this.started) return;
    try {
      const Ctx = window.AudioContext || window.webkitAudioContext;
      if (!Ctx) return;
      this.ctx = new Ctx();
      this.master = this.ctx.createGain();
      this.master.gain.value = this.volume;
      this.master.connect(this.ctx.destination);
      this.makeRain();
      this.makeHum();
      this.makeAmbientPad();
      this.started = true;
    } catch (e) { console.warn('Audio unavailable', e); }
  }

  setVolume(v) {
    this.volume = v;
    if (this.master) this.master.gain.setTargetAtTime(this.muted ? 0 : v, this.ctx.currentTime, .08);
  }

  toggleMute() {
    this.muted = !this.muted;
    if (this.master) this.master.gain.setTargetAtTime(this.muted ? 0 : this.volume, this.ctx.currentTime, .08);
  }

  noiseBuffer(seconds = 2) {
    const len = this.ctx.sampleRate * seconds;
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    return buf;
  }

  makeRain() {
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer(3); src.loop = true;
    const filter = this.ctx.createBiquadFilter(); filter.type = 'bandpass'; filter.frequency.value = 3400; filter.Q.value = .4;
    const hp = this.ctx.createBiquadFilter(); hp.type = 'highpass'; hp.frequency.value = 900;
    this.rainGain = this.ctx.createGain(); this.rainGain.gain.value = .055;
    src.connect(filter).connect(hp).connect(this.rainGain).connect(this.master);
    src.start();
  }

  makeHum() {
    const osc = this.ctx.createOscillator(); osc.type = 'sine'; osc.frequency.value = 56;
    const osc2 = this.ctx.createOscillator(); osc2.type = 'triangle'; osc2.frequency.value = 84.3;
    this.humGain = this.ctx.createGain(); this.humGain.gain.value = .018;
    osc.connect(this.humGain); osc2.connect(this.humGain); this.humGain.connect(this.master);
    osc.start(); osc2.start();
  }

  makeAmbientPad() {
    const freqs = [110, 164.81, 220, 277.18];
    this.padGains = freqs.map((f, i) => {
      const osc = this.ctx.createOscillator(); osc.type = i % 2 ? 'sine' : 'triangle'; osc.frequency.value = f;
      const detune = this.ctx.createOscillator(); detune.type = 'sine'; detune.frequency.value = .08 + i * .03;
      const dg = this.ctx.createGain(); dg.gain.value = 2.5; detune.connect(dg).connect(osc.detune); detune.start();
      const g = this.ctx.createGain(); g.gain.value = i === 0 ? .012 : .006;
      const filt = this.ctx.createBiquadFilter(); filt.type = 'lowpass'; filt.frequency.value = 700;
      osc.connect(filt).connect(g).connect(this.master); osc.start();
      return g;
    });
  }

  setWeather(kind) {
    if (!this.rainGain) return;
    const level = kind === 'storm' ? .13 : kind === 'heavy' ? .09 : kind === 'rain' ? .055 : kind === 'fog' ? .025 : .012;
    this.rainGain.gain.setTargetAtTime(level, this.ctx.currentTime, 1.5);
  }

  setFight(on) {
    this.fight = on;
    this.beatTimer = 0; this.step = 0;
    if (this.padGains) this.padGains.forEach((g,i) => g.gain.setTargetAtTime(on ? (i === 0 ? .018 : .008) : (i === 0 ? .012 : .006), this.ctx.currentTime, .4));
  }

  update(dt) {
    if (!this.started) return;
    this.thunderTimer -= dt;
    if (this.thunderTimer <= 0) {
      this.thunderTimer = 40 + Math.random() * 80;
      if (Math.random() < .55) this.thunder();
    }
    if (this.fight) {
      this.beatTimer -= dt;
      if (this.beatTimer <= 0) {
        this.beatTimer = .25;
        this.playBeat(this.step++ % 16);
      }
    }
  }

  tone(freq, dur, type = 'sine', gain = .08, slideTo = null, delay = 0) {
    if (!this.started || this.muted) return;
    const t = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator(); osc.type = type; osc.frequency.setValueAtTime(freq, t);
    if (slideTo) osc.frequency.exponentialRampToValueAtTime(Math.max(20, slideTo), t + dur);
    const g = this.ctx.createGain(); g.gain.setValueAtTime(.0001, t); g.gain.exponentialRampToValueAtTime(gain, t + .008); g.gain.exponentialRampToValueAtTime(.0001, t + dur);
    osc.connect(g).connect(this.master); osc.start(t); osc.stop(t + dur + .02);
  }

  noise(dur, freq = 1000, gain = .08, type = 'lowpass', delay = 0) {
    if (!this.started || this.muted) return;
    const t = this.ctx.currentTime + delay;
    const src = this.ctx.createBufferSource(); src.buffer = this.noiseBuffer(.4);
    const f = this.ctx.createBiquadFilter(); f.type = type; f.frequency.setValueAtTime(freq, t);
    const g = this.ctx.createGain(); g.gain.setValueAtTime(gain, t); g.gain.exponentialRampToValueAtTime(.0001, t + dur);
    src.connect(f).connect(g).connect(this.master); src.start(t); src.stop(t + dur + .02);
  }

  footstep(crouch, wet) {
    this.noise(crouch ? .06 : .08, wet ? 700 : 420, crouch ? .015 : .035, 'lowpass');
    if (wet) this.noise(.06, 3200, .012, 'highpass', .01);
  }

  jump() { this.tone(160, .12, 'sine', .035, 80); this.noise(.09, 800, .025); }
  land() { this.noise(.13, 260, .06); this.tone(70, .12, 'sine', .05, 40); }
  punch() { this.noise(.09, 900, .05, 'bandpass'); this.tone(110, .08, 'sine', .05, 55); }
  kick() { this.noise(.12, 500, .07, 'lowpass'); this.tone(90, .12, 'sine', .06, 40); }
  hit(power = 1) {
    this.noise(.12 * power, 220, .09 * power, 'lowpass');
    this.tone(70, .14, 'sine', .08 * power, 32);
    this.noise(.05, 2400, .025, 'highpass', .005);
  }
  block() { this.noise(.07, 1400, .04, 'bandpass'); this.tone(240, .05, 'square', .018, 180); }
  dodge() { this.noise(.14, 1200, .02, 'highpass'); }
  special() { this.tone(55, .5, 'sawtooth', .06, 160); this.noise(.3, 600, .06); setTimeout(() => this.tone(180, .3, 'square', .03, 60), 100); }
  ko() { this.tone(80, .6, 'sine', .1, 25); this.noise(.5, 180, .12); }
  ui() { this.tone(540, .05, 'square', .018, 700); }
  cash() { this.tone(880, .08, 'sine', .03, 1320); setTimeout(() => this.tone(1320, .1, 'sine', .025), 80); }
  thunder() {
    this.noise(1.7, 120, .1, 'lowpass');
    this.tone(36, 1.4, 'sine', .06, 24);
    setTimeout(() => this.noise(1.2, 90, .06, 'lowpass'), 500);
  }
  carStart() { this.tone(70, .2, 'sawtooth', .035, 110); this.noise(.2, 300, .04); }
  carStop() { this.tone(100, .2, 'sawtooth', .025, 40); }
  engine(speed) {
    if (!this.started) return;
    if (this.ctx.currentTime - this.lastEngine < .1) return;
    this.lastEngine = this.ctx.currentTime;
    this.tone(55 + speed * 40, .12, 'sawtooth', .012 + speed * .012, 50 + speed * 30);
  }
  playBeat(step) {
    const kick = step % 4 === 0;
    const snare = step === 4 || step === 12;
    const hat = step % 2 === 1;
    if (kick) { this.tone(52, .22, 'sine', .08, 32); }
    if (snare) { this.noise(.11, 1400, .05, 'bandpass'); this.tone(180, .09, 'triangle', .025, 100); }
    if (hat) { this.noise(.035, 8000, .012, 'highpass'); }
    if (step === 0 || step === 8) this.tone(110, .35, 'triangle', .018, 108);
  }
  speak() {
    // subtle NPC voice blip
    this.tone(180 + Math.random() * 80, .035, 'square', .008);
  }
}

import * as THREE from '../vendor/three.module.js';
import { BOSSES, STYLES } from './data.js';

const clamp = (v,a,b) => Math.max(a, Math.min(b, v));
const lerp = (a,b,t) => a + (b-a)*t;
const TAU = Math.PI * 2;

export class Combat {
  constructor(scene, camera, player, world, npcs, state, ui, audio) {
    this.scene = scene;
    this.camera = camera;
    this.player = player;
    this.world = world;
    this.npcs = npcs;
    this.state = state;
    this.ui = ui;
    this.audio = audio;
    this.active = false;
    this.enemy = null;
    this.boss = null;
    this.enemyHP = 100; this.enemyMax = 100;
    this.playerHP = 100; this.playerMax = 100;
    this.stamina = 100;
    this.special = 0;
    this.combo = 0; this.comboTimer = 0;
    this.cooldowns = { punch:0, kick:0, dodge:0, grapple:0, special:0, env:0 };
    this.enemyState = 'idle';
    this.enemyTimer = 1.2;
    this.enemyAttack = null;
    this.enemyCooldown = 1.5;
    this.enemySpecialCooldown = 7;
    this.enemyHits = 0;
    this.blocking = false;
    this.blockTime = 0;
    this.iframe = 0;
    this.slowmo = 1;
    this.finisherActive = false;
    this.finisherTimer = 0;
    this.endTimer = 0;
    this.endResult = null;
    this.startPos = null;
    this.arenaFight = false;
    this.hitFlash = 0;
    this.impactParticles = [];
    this.rings = [];
    this.lastPlayerAttack = 'punch';
    this.enemyStun = 0;
    this.playerStun = 0;
    this.callout = null;
    this.onEnd = null;
    this.damageNumbers = [];
    this.style = STYLES[state.player.style] || STYLES.street;
    this.streetProp = null;
  }

  get enemyPos() {
    if (!this.enemy) return { x:this.player.x, z:this.player.z };
    return { x:this.enemy.group.position.x, z:this.enemy.group.position.z };
  }

  get distance() {
    if (!this.enemy) return 99;
    return Math.hypot(this.enemy.group.position.x - this.player.x, this.enemy.group.position.z - this.player.z);
  }

  start(npc, opts = {}) {
    if (this.active || !npc) return false;
    this.active = true;
    this.enemy = npc;
    this.boss = opts.boss || null;
    this.arenaFight = !!opts.arena;
    this.onEnd = opts.onEnd || null;
    const boss = this.boss;
    this.enemyMax = boss ? boss.hp : 75 + Math.floor((this.state.player.level || 1) * 7);
    this.enemyHP = this.enemyMax;
    this.playerMax = 100 + ((this.state.player.level || 1) - 1) * 6;
    this.playerHP = clamp(this.state.player.health || this.playerMax, 1, this.playerMax);
    this.state.player.health = this.playerHP;
    this.stamina = this.state.player.stamina || 100;
    this.special = 0;
    this.combo = 0; this.comboTimer = 0;
    this.enemyState = 'approach';
    this.enemyTimer = 1.1;
    this.enemyCooldown = 1.6;
    this.enemySpecialCooldown = 6.5;
    this.enemyHits = 0;
    this.blocking = false; this.iframe = 0;
    this.slowmo = 1; this.finisherActive = false;
    this.endResult = null; this.endTimer = 0;
    this.enemyStun = 0; this.playerStun = 0;
    this.audio.setFight(true);
    this.ui.setCombat(true);
    this.ui.updateCombat(this.combatData());
    this.ui.showCallout(boss ? boss.title : 'STREET FIGHT');
    this.ui.toast(boss ? `${boss.name} // ${boss.style}` : `${npc.name} wants to throw hands.`, boss ? 'warn' : '');
    this.camera.fov = 66; this.camera.updateProjectionMatrix();
    // position
    const f = this.player.getForward();
    const dist = this.arenaFight ? 4.2 : 3.1;
    let tx = this.player.x + f.x * dist, tz = this.player.z + f.z * dist;
    if (this.world.isBlocked(tx, tz, .5)) { tx = this.player.x - f.x * dist; tz = this.player.z - f.z * dist; }
    npc.group.position.set(tx, 0, tz);
    npc.x = tx; npc.z = tz;
    npc.facing = Math.atan2(this.player.x - tx, this.player.z - tz);
    npc.group.rotation.y = npc.facing;
    npc.combat = true;
    npc.targetX = tx; npc.targetZ = tz;
    this.npcs.faceEachOther(npc, { x:this.player.x, z:this.player.z });
    this.player.yaw = Math.atan2(-(tx - this.player.x), -(tz - this.player.z));
    this.player.pitch = -.04;
    // style-specific
    this.style = STYLES[this.state.player.style] || STYLES.street;
    this.ui.setStyle(this.state.player.style);
    this.spawnRing(new THREE.Vector3(tx, .2, tz), boss ? new THREE.Color(boss.accent) : new THREE.Color(0xffb35c), 1.6, .6);
    this.audio.special();
    return true;
  }

  combatData() {
    return {
      active:this.active, playerHP:this.playerHP, playerMax:this.playerMax,
      enemyHP:this.enemyHP, enemyMax:this.enemyMax, stamina:this.stamina,
      special:this.special, combo:this.combo, enemyName:this.boss ? this.boss.name : (this.enemy?.name || 'UNKNOWN'),
      enemySub:this.boss ? this.boss.style : (this.enemy?.tag || 'STREET'),
      playerName:this.state.player.name || 'ROOKIE',
      style:this.style?.name || 'STREET',
      canFinish:this.enemyHP > 0 && this.enemyHP <= this.enemyMax * .2 && this.special >= 50
    };
  }

  updateUI() { this.ui.updateCombat(this.combatData()); }

  punch() {
    if (!this.active || this.endResult || this.finisherActive) return;
    if (this.cooldowns.punch > 0 || this.stamina < 5 || this.playerStun > 0) return;
    this.cooldowns.punch = .28;
    this.stamina -= 5;
    this.lastPlayerAttack = 'punch';
    this.player.animateAttack('punch');
    this.audio.punch();
    this.tryHit('punch');
  }

  kick() {
    if (!this.active || this.endResult || this.finisherActive) return;
    if (this.cooldowns.kick > 0 || this.stamina < 11 || this.playerStun > 0) return;
    this.cooldowns.kick = .52;
    this.stamina -= 11;
    this.lastPlayerAttack = 'kick';
    this.player.animateAttack('kick');
    this.audio.kick();
    this.tryHit('kick');
  }

  grapple() {
    if (!this.active || this.endResult || this.finisherActive) return;
    if (this.cooldowns.grapple > 0 || this.stamina < 15 || this.playerStun > 0) return;
    this.cooldowns.grapple = 1.1;
    this.stamina -= 15;
    this.player.animateAttack('punch');
    if (this.distance < 2.8) {
      const mult = this.state.player.style === 'wrestling' ? 1.7 : 1;
      this.hitEnemy(15 * mult, 'GRAPPLE', true);
      this.enemyStun = 1.1;
      this.player.addShake(.35);
      this.audio.hit(1.2);
    } else {
      this.ui.showCallout('TOO FAR');
    }
  }

  environment() {
    if (!this.active || this.endResult || this.finisherActive) return;
    if (this.cooldowns.env > 0 || this.stamina < 14) return;
    this.cooldowns.env = 2.4;
    this.stamina -= 14;
    const kind = this.arenaFight ? 'ring post' : ['trash can','loose brick','traffic cone','wet newspaper'][Math.floor(Math.random()*4)];
    this.ui.showCallout('ENVIRONMENT // ' + kind.toUpperCase());
    this.player.animateAttack('punch');
    setTimeout(() => {
      if (!this.active) return;
      if (this.distance < 4.2) {
        this.hitEnemy(11 + Math.floor(Math.random()*7), 'ENVIRONMENT', true);
        this.enemyStun = .7;
        this.audio.impact?.(1); this.audio.hit(1);
        const pos = new THREE.Vector3(this.enemyPos.x, 1.2, this.enemyPos.z);
        this.spawnImpact(pos, new THREE.Color(0xffb35c), 20);
      }
    }, 220);
  }

  tryHit(type) {
    const inRange = type === 'kick' ? this.distance < 3.15 : this.distance < 2.55;
    if (!inRange) return;
    let dmg = type === 'kick' ? 11 : 7;
    dmg += (this.state.player.strength || 1) * 1.4;
    if (this.state.player.style === 'muay' && type === 'kick') dmg *= 1.35;
    if (this.state.player.style === 'street') dmg *= 1.08;
    if (this.enemyStun > 0) dmg *= 1.25;
    if (this.enemyState === 'block') dmg *= .25;
    const comboMult = 1 + Math.min(this.combo, 8) * .055;
    dmg *= comboMult;
    this.hitEnemy(dmg, type.toUpperCase());
    this.special = clamp(this.special + (type === 'kick' ? 8 : 5), 0, 100);
    this.combo++;
    this.comboTimer = 2.2;
    this.player.addShake(type === 'kick' ? .24 : .14);
    this.audio.hit(type === 'kick' ? 1.25 : .8);
    const pos = new THREE.Vector3(this.enemyPos.x, 1.25, this.enemyPos.z);
    this.spawnImpact(pos, new THREE.Color(type === 'kick' ? 0xffb35c : 0x7fe3d2), type === 'kick' ? 16 : 10);
    if (this.combo >= 3) this.ui.showCombo(this.combo);
    if (this.boss?.id === 'student' && this.enemyState === 'counter') {
      this.counterPlayer(9);
      this.ui.showCallout('RED PEN COUNTER');
    }
  }

  hitEnemy(dmg, label, heavy = false) {
    if (!this.active || this.enemyHP <= 0) return;
    const rounded = Math.round(dmg);
    this.enemyHP = Math.max(0, this.enemyHP - rounded);
    this.npcs.playHit(this.enemy);
    this.ui.damageNumber(rounded, this.enemyPos, this.camera);
    if (heavy) this.enemyStun = Math.max(this.enemyStun, .5);
    if (this.enemyHP <= 0) this.win();
  }

  counterPlayer(dmg) {
    this.playerHP = Math.max(0, this.playerHP - dmg);
    this.state.player.health = this.playerHP;
    this.player.addShake(.5);
    this.audio.hit(1.2);
    this.ui.flashHit();
    this.combo = 0;
    if (this.playerHP <= 0) this.lose();
  }

  specialAttack() {
    if (!this.active || this.endResult || this.finisherActive) return;
    if (this.special < 100 || this.cooldowns.special > 0) {
      if (this.special < 100) this.ui.showCallout('SPECIAL NOT READY');
      return;
    }
    this.special = 0;
    this.cooldowns.special = 1.2;
    this.slowmo = .32;
    this.audio.special();
    this.player.animateAttack('special');
    this.player.addShake(.8);
    this.ui.showCallout(this.style.special);
    this.camera.fov = 78; this.camera.updateProjectionMatrix();
    this.spawnRing(new THREE.Vector3(this.player.x, .3, this.player.z), new THREE.Color(this.style.color || '#ff4338'), 1, 1.8);
    setTimeout(() => {
      if (!this.active) return;
      const dmg = (this.style.name === 'MUAY THAI' ? 36 : this.style.name === 'WRESTLING' ? 40 : this.style.name === 'FLOW' ? 32 : 34) + (this.state.player.strength || 1) * 2;
      if (this.distance < 4.5) {
        this.hitEnemy(dmg, this.style.special, true);
        this.enemyStun = 1.2;
        this.spawnImpact(new THREE.Vector3(this.enemyPos.x, 1.3, this.enemyPos.z), new THREE.Color(this.style.color || '#ff4338'), 34);
        this.audio.hit(1.7);
      } else {
        this.enemyHP = Math.max(0, this.enemyHP - 4);
        this.ui.showCallout('GRAZED');
      }
      this.slowmo = 1;
      this.camera.fov = 66; this.camera.updateProjectionMatrix();
      if (this.enemyHP <= 0) this.win();
    }, 600);
  }

  finisher() {
    if (!this.active || this.finisherActive || this.endResult) return;
    if (this.enemyHP > this.enemyMax * .2 || this.special < 50) return;
    this.finisherActive = true;
    this.finisherTimer = 2.5;
    this.slowmo = .18;
    this.special = 0;
    this.player.cinematic = true;
    this.audio.special();
    this.ui.showCallout('FINISH');
    this.ui.showFinisher(false);
    this.camera.fov = 55; this.camera.updateProjectionMatrix();
    this.player.addShake(1.2);
    this.spawnRing(new THREE.Vector3(this.enemyPos.x, .5, this.enemyPos.z), new THREE.Color(0xff4338), 1, 3);
    setTimeout(() => {
      if (!this.active) return;
      this.enemyHP = 0;
      this.npcs.playHit(this.enemy);
      this.spawnImpact(new THREE.Vector3(this.enemyPos.x, 1.2, this.enemyPos.z), new THREE.Color(0xff4338), 50);
      this.audio.ko();
      this.player.addShake(1.5);
      this.ui.flashHit();
      this.win();
      this.finisherActive = false;
      this.player.cinematic = false;
      this.slowmo = 1;
      this.camera.fov = 66; this.camera.updateProjectionMatrix();
    }, 1300);
  }

  win() {
    if (this.endResult) return;
    this.endResult = 'win';
    this.endTimer = 2.1;
    this.enemyState = 'defeated';
    this.enemyHP = 0;
    this.slowmo = .35;
    this.player.cinematic = true;
    this.audio.ko();
    this.ui.showCallout('KNOCKOUT');
    this.ui.updateCombat(this.combatData());
    this.spawnRing(new THREE.Vector3(this.enemyPos.x, .2, this.enemyPos.z), new THREE.Color(0xffb35c), 2, 2.6);
    setTimeout(() => {
      this.enemy.group.rotation.z = .9;
      this.enemy.group.position.y = .1;
    }, 300);
  }

  lose() {
    if (this.endResult) return;
    this.endResult = 'lose';
    this.endTimer = 2.4;
    this.playerHP = 0;
    this.state.player.health = 0;
    this.slowmo = .3;
    this.audio.ko();
    this.ui.showCallout('KNOCKED OUT');
    this.ui.flashHit();
    this.player.addShake(1.2);
    this.player.cinematic = true;
  }

  finishCombat() {
    const result = this.endResult;
    const enemy = this.enemy;
    const boss = this.boss;
    this.active = false;
    this.enemy = null;
    this.boss = null;
    this.player.cinematic = false;
    this.slowmo = 1;
    this.player.blocking = false;
    this.blocking = false;
    this.camera.fov = 72; this.camera.updateProjectionMatrix();
    this.ui.setCombat(false);
    this.audio.setFight(false);
    if (enemy) {
      enemy.combat = false;
      enemy.group.rotation.z = 0; enemy.group.position.y = 0;
    }
    this.endResult = null;
    this.finisherActive = false;
    this.cleanupEffects();
    if (this.onEnd) { const cb = this.onEnd; this.onEnd = null; cb(result, enemy, boss); }
  }

  cleanupEffects() {
    for (const p of this.impactParticles) { this.scene.remove(p.mesh); p.mesh.geometry.dispose?.(); }
    this.impactParticles = [];
    for (const r of this.rings) { this.scene.remove(r.mesh); r.mesh.geometry.dispose?.(); }
    this.rings = [];
  }

  spawnImpact(pos, color, count = 12) {
    const geo = new THREE.BufferGeometry();
    const arr = new Float32Array(count * 3);
    for (let i = 0; i < count; i++) { arr[i*3]=0; arr[i*3+1]=0; arr[i*3+2]=0; }
    geo.setAttribute('position', new THREE.BufferAttribute(arr, 3));
    const mat = new THREE.PointsMaterial({ color, size:.11, transparent:true, opacity:1, depthWrite:false, blending:THREE.AdditiveBlending });
    const mesh = new THREE.Points(geo, mat); mesh.position.copy(pos); this.scene.add(mesh);
    const vel = [];
    for (let i = 0; i < count; i++) vel.push(new THREE.Vector3((Math.random()-.5)*8, Math.random()*6, (Math.random()-.5)*8));
    this.impactParticles.push({ mesh, vel, life:1 });
  }

  spawnRing(pos, color, inner = 1, duration = .7) {
    const geo = new THREE.RingGeometry(.82, 1, 40);
    const mat = new THREE.MeshBasicMaterial({ color, transparent:true, opacity:.8, side:THREE.DoubleSide, depthWrite:false, blending:THREE.AdditiveBlending });
    const mesh = new THREE.Mesh(geo, mat); mesh.rotation.x = -Math.PI/2; mesh.position.copy(pos); this.scene.add(mesh);
    this.rings.push({ mesh, life:duration, max:duration, inner });
  }

  triggerBossSpecial() {
    if (!this.boss || this.endResult) return;
    const b = this.boss;
    const ability = b.abilities[Math.floor(Math.random() * b.abilities.length)];
    this.ui.showCallout(ability.toUpperCase());
    this.audio.special();
    this.spawnRing(new THREE.Vector3(this.enemyPos.x, .3, this.enemyPos.z), new THREE.Color(b.accent), 1, 1.4);
    this.enemyState = 'special';
    this.enemyTimer = 1.15;
    this.enemyAttack = { type:'boss', ability, damage:b.dmg * 1.5 };
    if (b.id === 'raincoat') {
      const f = this.player.getForward();
      this.enemy.group.position.set(this.player.x - f.x * 2.3, 0, this.player.z - f.z * 2.3);
      this.enemy.x = this.enemy.group.position.x; this.enemy.z = this.enemy.group.position.z;
    }
    if (b.id === 'ferryman') {
      const dx = this.enemyPos.x - this.player.x, dz = this.enemyPos.z - this.player.z;
      const d = Math.hypot(dx,dz) || 1;
      this.player.x += dx / d * 1.5; this.player.z += dz / d * 1.5;
      this.player.addShake(.25);
    }
    if (b.id === 'future' && this.enemyHP < this.enemyMax * .6) this.enemyHP = Math.min(this.enemyMax, this.enemyHP + 8);
    if (b.id === 'mayor') this.playerStun = 1.2;
    if (b.id === 'hiker') this.playerStun = .8;
    if (b.id === 'oldman') this.slowmo = .55;
    setTimeout(() => {
      if (!this.active || this.endResult) return;
      const dist = this.distance;
      const blocked = this.blocking;
      if (dist < 5.2 || b.id === 'mayor' || b.id === 'ferryman') {
        let dmg = b.dmg * (1.1 + Math.random() * .6);
        if (blocked) dmg *= .32;
        if (this.iframe > 0) dmg = 0;
        if (b.id === 'mirror' && this.lastPlayerAttack === 'kick') dmg *= 1.2;
        if (b.id === 'student' && this.lastPlayerAttack) dmg *= 1.15;
        if (dmg > 0) {
          this.playerHP = Math.max(0, this.playerHP - Math.round(dmg));
          this.state.player.health = this.playerHP;
          this.player.addShake(.7);
          this.ui.flashHit();
          this.audio.hit(1.2);
          this.spawnImpact(new THREE.Vector3(this.player.x, 1.2, this.player.z), new THREE.Color(b.accent), 22);
          this.combo = 0;
          if (this.playerHP <= 0) this.lose();
        } else this.ui.showCallout('DODGED');
      }
      this.slowmo = 1;
      this.enemyState = 'recover';
      this.enemyTimer = 1.2;
    }, 850);
  }

  update(dt) {
    if (!this.active) return;
    this.updateUI();
    if (this.endResult) {
      this.endTimer -= dt;
      this.slowmo = lerp(this.slowmo, 1, dt * 2);
      this.updateEffects(dt);
      if (this.endTimer <= 0) this.finishCombat();
      return;
    }
    if (this.finisherActive) {
      this.updateEffects(dt * .2);
      return;
    }
    const scaled = dt * this.slowmo;
    for (const k in this.cooldowns) this.cooldowns[k] = Math.max(0, this.cooldowns[k] - dt);
    this.iframe = Math.max(0, this.iframe - dt);
    this.enemyStun = Math.max(0, this.enemyStun - scaled);
    this.playerStun = Math.max(0, this.playerStun - dt);
    this.comboTimer -= dt;
    if (this.comboTimer <= 0) this.combo = 0;
    this.stamina = clamp(this.stamina + dt * 11, 0, 100);
    this.state.player.stamina = this.stamina;
    this.state.player.health = this.playerHP;
    this.special = clamp(this.special + dt * .65, 0, 100);
    this.player.blocking = this.blocking;

    // player movement is normal; keep facing target when close
    if (this.distance < 5.5) {
      const targetYaw = Math.atan2(-(this.enemyPos.x - this.player.x), -(this.enemyPos.z - this.player.z));
      let diff = ((targetYaw - this.player.yaw + Math.PI * 3) % TAU) - Math.PI;
      if (Math.abs(diff) > .35) this.player.yaw += diff * dt * .8;
    }
    // clamp to arena
    if (this.arenaFight) {
      const a = this.world.arena;
      const d = Math.hypot(this.player.x - a.x, this.player.z - a.z);
      if (d > 11) {
        const ang = Math.atan2(this.player.z - a.z, this.player.x - a.x);
        this.player.x = a.x + Math.cos(ang) * 10.7; this.player.z = a.z + Math.sin(ang) * 10.7;
      }
    }

    // enemy AI
    if (this.enemy && !this.endResult) {
      const npc = this.enemy;
      const ex = npc.group.position.x, ez = npc.group.position.z;
      const dx = this.player.x - ex, dz = this.player.z - ez;
      const dist = Math.hypot(dx, dz) || .001;
      npc.facing = Math.atan2(dx, dz);
      npc.group.rotation.y = npc.facing;
      npc.group.position.y = 0;
      if (this.enemyState !== 'attack' && this.enemyState !== 'special' && this.enemyState !== 'stagger' && this.enemyState !== 'counter') {
        this.enemyTimer -= scaled;
        this.enemyCooldown -= scaled;
        this.enemySpecialCooldown -= scaled;
        // movement
        let moveSpeed = (this.boss ? 2.1 : 1.6) * (this.boss?.speed || 1);
        if (this.boss?.id === 'barista') moveSpeed *= 1.25;
        if (this.boss?.id === 'oldman') moveSpeed *= .7;
        if (dist > 2.7) {
          const nx = ex + dx / dist * moveSpeed * scaled;
          const nz = ez + dz / dist * moveSpeed * scaled;
          if (!this.world.isBlocked(nx, nz, .4)) { npc.group.position.x = nx; npc.group.position.z = nz; }
        } else if (dist < 1.65) {
          npc.group.position.x -= dx / dist * moveSpeed * .55 * scaled;
          npc.group.position.z -= dz / dist * moveSpeed * .55 * scaled;
        } else {
          const side = Math.sin(this.enemyTimer * 1.7) * .55;
          const nx = ex + (-dz / dist) * side * scaled, nz = ez + (dx / dist) * side * scaled;
          if (!this.world.isBlocked(nx, nz, .4)) { npc.group.position.x = nx; npc.group.position.z = nz; }
        }
        npc.x = npc.group.position.x; npc.z = npc.group.position.z;
        if (this.enemySpecialCooldown <= 0 && this.boss) {
          this.enemySpecialCooldown = 6 + Math.random() * 4;
          this.triggerBossSpecial();
        } else if (this.enemyCooldown <= 0 && dist < 3.4) {
          this.enemyState = 'windup';
          this.enemyTimer = .55;
          this.enemyAttack = { type:'strike', damage:this.boss ? this.boss.dmg : 8 + Math.random()*5 };
          this.ui.showCallout('INCOMING');
          this.enemyHits++;
          if (this.boss?.id === 'student' && Math.random() < .28) this.enemyState = 'counter';
        }
      } else if (this.enemyState === 'windup') {
        this.enemyTimer -= scaled;
        // telegraph glow
        npc.model.torso.material.emissive = new THREE.Color(0xff4338);
        npc.model.torso.material.emissiveIntensity = .25 + Math.sin(this.enemyTimer * 30) * .1;
        if (this.enemyTimer <= 0) {
          npc.model.torso.material.emissiveIntensity = 0;
          if (this.enemyAttack?.type === 'strike') {
            const hit = this.distance < 3.0;
            if (hit && this.iframe <= 0) {
              let dmg = this.enemyAttack.damage;
              if (this.blocking) dmg *= .22;
              if (this.blocking && this.blockTime < .25) {
                this.ui.showCallout('COUNTER');
                this.hitEnemy(8 + (this.state.player.strength||1), 'COUNTER', true);
                this.special = clamp(this.special + 15, 0, 100);
                this.audio.block();
                this.enemyStun = .8;
              } else {
                this.playerHP = Math.max(0, this.playerHP - Math.round(dmg));
                this.state.player.health = this.playerHP;
                this.player.addShake(.5);
                this.audio.hit(.9);
                this.ui.flashHit();
                this.spawnImpact(new THREE.Vector3(this.player.x, 1.2, this.player.z), new THREE.Color(0xff4338), 14);
                this.combo = 0;
                if (this.playerHP <= 0) this.lose();
              }
            }
          }
          this.enemyState = 'recover';
          this.enemyTimer = .55 + Math.random() * .5;
          this.enemyCooldown = 1.1 + Math.random() * 1.1;
        }
      } else if (this.enemyState === 'recover' || this.enemyState === 'stagger') {
        this.enemyTimer -= scaled;
        if (this.enemyTimer <= 0) this.enemyState = 'approach';
      } else if (this.enemyState === 'counter') {
        this.enemyTimer -= scaled;
        npc.model.torso.material.emissive = new THREE.Color(0xd9a6ff);
        npc.model.torso.material.emissiveIntensity = .18;
        if (this.enemyTimer <= 0) { npc.model.torso.material.emissiveIntensity = 0; this.enemyState = 'approach'; this.enemyCooldown = .7; }
      } else if (this.enemyState === 'special') {
        this.enemyTimer -= scaled;
        if (this.enemyTimer <= 0) this.enemyState = 'recover';
      }
      // enemy animation
      const m = npc.model;
      if (this.enemyState === 'windup') { m.leftArm.rotation.x = -1.4; m.rightArm.rotation.x = -1.4; }
      else if (this.enemyState === 'attack') { m.rightArm.rotation.x = -.2; }
      else {
        const t = performance.now() * .004;
        m.leftArm.rotation.x = Math.sin(t) * .25; m.rightArm.rotation.x = -Math.sin(t) * .25;
      }
      m.leftLeg.rotation.x *= .9; m.rightLeg.rotation.x *= .9;
    }
    this.updateEffects(dt);
    this.hitFlash = Math.max(0, this.hitFlash - dt);
    if (this.hitFlash > 0) this.camera.rotation.z = (Math.random()-.5) * .01;
  }

  updateEffects(dt) {
    for (let i = this.impactParticles.length - 1; i >= 0; i--) {
      const p = this.impactParticles[i];
      p.life -= dt * 2.2;
      const pos = p.mesh.geometry.attributes.position;
      for (let j = 0; j < p.vel.length; j++) {
        p.vel[j].y -= 9 * dt;
        pos.array[j*3] += p.vel[j].x * dt;
        pos.array[j*3+1] += p.vel[j].y * dt;
        pos.array[j*3+2] += p.vel[j].z * dt;
      }
      pos.needsUpdate = true;
      p.mesh.material.opacity = clamp(p.life, 0, 1);
      if (p.life <= 0) { this.scene.remove(p.mesh); p.mesh.geometry.dispose(); p.mesh.material.dispose(); this.impactParticles.splice(i,1); }
    }
    for (let i = this.rings.length - 1; i >= 0; i--) {
      const r = this.rings[i];
      r.life -= dt;
      const t = 1 - r.life / r.max;
      r.mesh.scale.setScalar(1 + t * 7);
      r.mesh.material.opacity = (1 - t) * .7;
      if (r.life <= 0) { this.scene.remove(r.mesh); r.mesh.geometry.dispose(); r.mesh.material.dispose(); this.rings.splice(i,1); }
    }
  }
}

import { DISTRICTS, BUSINESSES, RANKS, WEATHER, STYLES } from './data.js';

const $ = (id) => document.getElementById(id);
const clamp = (v,a,b) => Math.max(a, Math.min(b, v));
const fmt = (n) => '$' + Math.round(n).toLocaleString('en-US');

export class UI {
  constructor(world, state) {
    this.world = world;
    this.state = state;
    this.objective = null;
    this.player = null;
    this.waypoint = null;
    this.menuOpen = false;
    this.dialogueOpen = false;
    this.panelOpen = false;
    this.mapOpen = false;
    this.combat = false;
    this.dialogueCallback = null;
    this.panelCallback = null;
    this.modalCallback = null;
    this.minimapCtx = $('minimap').getContext('2d');
    this.bigmapCtx = $('bigmap').getContext('2d');
    this.typeTimer = null;
    this.toastTimers = [];
    this._lastHud = 0;
    this._areaTimer = null;
    this.bindMap();
  }

  bootProgress(p, text) {
    const bar = document.querySelector('.boot-line span');
    if (bar) bar.style.width = Math.round(p * 100) + '%';
    $('boot-text').textContent = text || 'READING THE RAIN...';
  }

  hideBoot() {
    $('boot').classList.add('out');
    setTimeout(() => $('boot').classList.add('hidden'), 800);
  }

  showMenu(hasSave) {
    $('menu').classList.remove('hidden');
    $('btn-start').disabled = false;
    $('btn-continue').classList.toggle('hidden', !hasSave);
    this.menuOpen = true;
  }

  hideMenu() {
    $('menu').classList.add('fading');
    setTimeout(() => { $('menu').classList.add('hidden'); $('menu').classList.remove('fading'); }, 680);
    this.menuOpen = false;
  }

  showHUD() { $('hud').classList.remove('hidden'); }
  hideHUD() { $('hud').classList.add('hidden'); }
  showTouch(on) { $('touch').classList.toggle('visible', on); $('touch').classList.remove('hidden'); }
  hideTouch() { $('touch').classList.add('hidden'); $('touch').classList.remove('visible'); }

  setPlayer(player) { this.player = player; }

  setObjective(objective) { this.objective = objective; }

  updateHUD(force = false) {
    if (!this.player || !this.state) return;
    const now = performance.now();
    if (!force && now - this._lastHud < 90) return;
    this._lastHud = now;
    const p = this.state.player;
    const t = this.state.time;
    const h = Math.floor(t.minutes / 60) % 24, m = Math.floor(t.minutes % 60);
    $('clock-time').textContent = String(h).padStart(2,'0') + ':' + String(m).padStart(2,'0');
    const days = ['MON','TUE','WED','THU','FRI','SAT','SUN'];
    $('clock-day').textContent = `${days[t.day % 7]} · DAY ${t.day + 1}`;
    const w = WEATHER[this.state.weather] || WEATHER.rain;
    $('weather-label').textContent = w.label;
    $('weather-icon').textContent = w.icon;
    $('temp-label').textContent = w.temp + '°';
    $('wallet').textContent = fmt(p.money);
    $('rep-label').textContent = this.rank(p.reputation || 0).toUpperCase();
    $('style-chip').textContent = 'STYLE // ' + (STYLES[p.style]?.name || 'STREET');
    for (const need of ['hunger','energy','hygiene','mood']) {
      const el = $('need-' + need);
      if (!el) continue;
      const val = clamp(p[need] ?? 70, 0, 100);
      el.style.width = val + '%';
      const parent = el.closest('.need');
      parent?.classList.toggle('low', val < 24);
    }
    if (this.objective) {
      $('quest-chapter').textContent = this.objective.chapter || 'CHAPTER';
      $('quest-title').textContent = this.objective.title || '';
      $('quest-objective').textContent = this.objective.objective || '';
      const target = this.objective.targetPos;
      let dist = '';
      if (target) dist = Math.round(Math.hypot(this.player.x - target.x, this.player.z - target.z)) + ' m';
      $('quest-dist').textContent = dist;
      const prog = this.objective.progress ?? 0;
      $('quest-progress').style.width = Math.round(prog * 100) + '%';
    }
    const d = this.world.districtAt(this.player.x, this.player.z);
    $('hud-location').textContent = d.name;
    $('minimap-tag').textContent = d.name;
    this.drawMinimap();
    $('weirdness').classList.toggle('show', (this.state.weirdness || .1) > .28);
    $('weirdness').style.setProperty('--weird', Math.round((this.state.weirdness || .1) * 100) + '%');
    $('weirdness').querySelector('span').textContent = this.state.weirdness > .78 ? 'THE CITY IS LISTENING' : this.state.weirdness > .5 ? 'THE CITY IS LOOKING' : 'SOMETHING IS OFF';
  }

  rank(rep) {
    let r = RANKS[0];
    for (const x of RANKS) if (rep >= x.min) r = x;
    return r.name;
  }

  drawMinimap() {
    const c = this.minimapCtx;
    const W = 184, H = 184;
    c.clearRect(0,0,W,H);
    c.save();
    c.beginPath(); c.arc(W/2,H/2,W/2-1,0,Math.PI*2); c.clip();
    c.fillStyle = '#0a1112'; c.fillRect(0,0,W,H);
    const scale = 1.38;
    const px = this.player?.x || 0, pz = this.player?.z || 0;
    const tx = (x) => W/2 + (x - px) * scale;
    const tz = (z) => H/2 + (z - pz) * scale;
    // water
    c.fillStyle = '#0d2028';
    if (pz < 200) { c.fillRect(0, tz(244), W, H); }
    if (px > 230) { c.fillRect(tx(260), 0, W, H); }
    // roads
    c.strokeStyle = '#3d4746'; c.lineWidth = 2;
    for (const x of this.world.roadXs || []) { c.beginPath(); c.moveTo(tx(x),0); c.lineTo(tx(x),H); c.stroke(); }
    for (const z of this.world.roadZs || []) { c.beginPath(); c.moveTo(0,tz(z)); c.lineTo(W,tz(z)); c.stroke(); }
    // district tint
    for (const d of DISTRICTS) {
      const dx = tx(d.x), dz = tz(d.z);
      if (dx > -80 && dx < W+80 && dz > -80 && dz < H+80) {
        c.fillStyle = d.color + '12'; c.beginPath(); c.arc(dx,dz,d.r*scale*.6,0,Math.PI*2); c.fill();
      }
    }
