.phone-objective{border:1px solid var(--line);border-left:2px solid var(--red);padding:12px 14px;display:flex;flex-direction:column;gap:5px}
.phone-objective b{font-family:Bebas,sans-serif;font-size:22px;font-weight:400;letter-spacing:.05em}
.phone-objective span{font-size:10px;color:var(--paper-dim);line-height:1.5}
.phone-contact{display:flex;align-items:center;gap:12px;border-bottom:1px solid rgba(255,255,255,.07);padding:10px 0}
.phone-contact-main{flex:1;min-width:0}
.phone-contact-main b{font-size:12px;display:block}
.phone-contact-main>span{font-family:Plex,monospace;font-size:7px;letter-spacing:.12em;color:var(--paper-faint)}
.phone-bars{display:flex;gap:3px;margin-top:6px}
.phone-bars i{height:3px;flex:1;background:rgba(255,255,255,.08);display:block;overflow:hidden}
.phone-bars em{display:block;height:100%;background:var(--teal)}
.phone-bars i.rom em{background:#d9a6ff}
.phone-bars i.gr em{background:var(--red)}
.phone-skill-head{display:flex;justify-content:space-between;align-items:baseline;border-bottom:1px solid var(--line);padding-bottom:10px;margin-bottom:14px;font-family:Plex,monospace;font-size:8px;letter-spacing:.18em;color:var(--paper-faint)}
.phone-skill-head b{font-family:Bebas,sans-serif;font-size:32px;color:var(--teal);font-weight:400}

/* ---------- endings ---------- */
.ending-list{display:flex;flex-direction:column;gap:7px;margin:16px 0}
.ending-option{display:flex;justify-content:space-between;gap:14px;border:1px solid var(--line);padding:10px 12px;background:rgba(255,255,255,.025)}
.ending-option.locked{opacity:.45}
.ending-option b{display:block;font-family:Bebas,sans-serif;font-size:19px;font-weight:400;letter-spacing:.05em;line-height:1.1}
.ending-option span{display:block;font-size:9px;line-height:1.45;color:var(--paper-dim);margin-top:3px}
.ending-option em{display:block;font-family:Plex,monospace;font-size:7px;font-style:normal;letter-spacing:.1em;color:var(--paper-faint);margin-top:5px}
.ending-state{font-family:Plex,monospace;font-size:7px;letter-spacing:.14em;color:var(--teal);white-space:nowrap;align-self:center}
.ending-option.locked .ending-state{color:var(--red)}
.ending-copy{font-size:11px;line-height:1.8;color:#b9b7ad}
#modal-actions{display:flex;flex-wrap:wrap;gap:7px;margin-top:20px}
#modal-actions .btn{font-size:8px;min-height:42px;padding:0 14px;letter-spacing:.12em}

/* ---------- misc ---------- */
.damage-number{position:fixed;z-index:26;font-family:Bebas,sans-serif;font-size:28px;color:var(--amber);text-shadow:0 2px 10px #000;pointer-events:none;transform:translate(-50%,-50%)}
.reduced-motion *{animation-duration:.001ms!important;animation-iteration-count:1!important;transition-duration:.001ms!important}
.is-touch .look-hint{display:none}
.touch-fight button.on{border-color:var(--red);color:var(--red);background:rgba(255,67,56,.12)}

@media (max-width:640px){
  .phone-cols{grid-template-columns:1fr;gap:8px}
  .timing-wrap{margin-top:3vh}
  .ending-option{flex-direction:column;gap:6px}
  .ending-state{align-self:flex-start}
}
