function noCash() { ui.toast('<b>NO CASH</b> · The city does not extend credit to strangers.', 'warn'); }

function closePanel() {
  ui.closePanel();
  gameMode = 'play';
  saveGame(true);
}

function finishShift(hits) {
  const p = state.player;
  const pay = 55 + hits * 22;
  p.money += pay; p.energy = clamp(p.energy - 28, 0, 100); p.hunger = clamp(p.hunger - 8, 0, 100);
  state.time.minutes += 240; state.stats.shifts++; p.xp += 35; checkLevel();
  closePanel();
  saveGame(true);
  ui.toast(`<b>SHIFT COMPLETE</b> · ${fmt(pay)}. The espresso machine sighs.`, '');
  if (!state.flags.workedShift) {
    state.flags.workedShift = true;
    state.weirdness = clamp(state.weirdness + .08, 0, 1); world.setWeirdness(state.weirdness);
    setQuestStage(1);
    setTimeout(async () => {
      await ui.cinematic('MONDAY · 12:04 PM', 'ROUND ONE', 'Mara is already looking at you.');
      ui.showEvent('ROUND ONE', 'Mara says it like a weather report. The sign flips to CLOSED by itself.');
      ui.toast('<b>NEW OBJECTIVE</b> · Follow the unmarked bus at the Transit Center.', 'warn');
    }, 700);
  }
}

function checkLevel() {
  const p = state.player;
  const next = 100 + (p.level - 1) * 75;
  while (p.xp >= next * p.level / 1.5) {
    p.level++;
    p.skillPoints = (p.skillPoints || 0) + 1;
    p.health = clamp(p.health + 10, 0, 100);
    ui.toast(`<b>LEVEL ${p.level}</b> · +1 skill point. The city notices.`, '');
  }
}

export class Audio {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.volume = .55;
    this.muted = false;
    this.started = false;
    this.rainGain = null;
    this.humGain = null;
    this.fight = false;
    this.beatTimer = 0;
    this.step = 0;
    this.thunderTimer = 35;
    this.lastEngine = 0;
    this.engineOsc = null;
    this.engineGain = null;
  }

  init() {
    if (this.started) return;
    try {
      const Ctx = window.AudioContext || window.webkitAudioContext;
      if (!Ctx) return;
      this.ctx = new Ctx();
      this.master = this.ctx.createGain();
      this.master.gain.value = this.volume;
      this.master.connect(this.ctx.destination);
      this.makeRain();
      this.makeHum();
      this.makeAmbientPad();
      this.started = true;
    } catch (e) { console.warn('Audio unavailable', e); }
  }

  setVolume(v) {
    this.volume = v;
    if (this.master) this.master.gain.setTargetAtTime(this.muted ? 0 : v, this.ctx.currentTime, .08);
  }

  toggleMute() {
    this.muted = !this.muted;
    if (this.master) this.master.gain.setTargetAtTime(this.muted ? 0 : this.volume, this.ctx.currentTime, .08);
  }

  noiseBuffer(seconds = 2) {
    const len = this.ctx.sampleRate * seconds;
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    return buf;
  }

  makeRain() {
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer(3); src.loop = true;
    const filter = this.ctx.createBiquadFilter(); filter.type = 'bandpass'; filter.frequency.value = 3400; filter.Q.value = .4;
    const hp = this.ctx.createBiquadFilter(); hp.type = 'highpass'; hp.frequency.value = 900;
    this.rainGain = this.ctx.createGain(); this.rainGain.gain.value = .055;
    src.connect(filter).connect(hp).connect(this.rainGain).connect(this.master);
    src.start();
  }

  makeHum() {
