import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';
const browser = await chromium.launch({ headless: true, args: ['--use-gl=swiftshader','--enable-webgl','--ignore-gpu-blocklist'] });
const page = await browser.newPage({ viewport: { width: 900, height: 560 } });
await page.addInitScript(() => { HTMLCanvasElement.prototype.requestPointerLock = function(){}; document.exitPointerLock = function(){}; });
const errors=[]; page.on('console',m=>{if(m.type()==='error')errors.push('CONSOLE '+m.text());}); page.on('pageerror',e=>errors.push('PAGEERROR '+e.message));
const ev=(fn,arg)=>page.evaluate(fn,arg);
const waitFor=async(fn,l,t=30000)=>{const s=Date.now();while(Date.now()-s<t){if(await fn())return true;await page.waitForTimeout(200);}console.log('TIMEOUT',l);return false;};
await page.goto('http://127.0.0.1:8123/', { waitUntil:'load' });
await page.waitForTimeout(9000);
await ev(()=>document.getElementById('btn-start').click());
await page.waitForTimeout(500);
const gate = await ev(()=>({ modal:!document.getElementById('modal').classList.contains('hidden'), title:document.getElementById('modal-title').textContent, actions:[...document.querySelectorAll('#modal-actions button')].map(b=>b.textContent) }));
console.log('CONSENT GATE', JSON.stringify(gate));
await ev(()=>{ const b=[...document.querySelectorAll('#modal-actions button')].find(x=>x.textContent.includes('18')); b?.click(); });
await waitFor(async()=>(await ev(()=>window.__BELLINGHAM?.mode))==='play','play after consent',15000);
console.log('PLAY', await ev(()=>({mode:window.__BELLINGHAM.mode, stage:window.__BELLINGHAM.state.quest.stage})));

// generated encounters
const enc = await ev(()=>{ const g=window.__BELLINGHAM; let gen=0; for(let i=0;i<40;i++){ g.triggerRandomEvent(); } return { events:g.state.stats.events }; });
console.log('EVENTS', JSON.stringify(enc));
const genCount = await ev(async()=>{ const m=await import('./src/data.js'); return { events:m.EVENTS.length, generated:m.ENCOUNTERS.length }; });
console.log('POOL', JSON.stringify(genCount));

// boss + ending
await ev(()=>{const g=window.__BELLINGHAM;g.state.quest.stage=2;g.state.player.health=100;g.setMode('play');g.startArenaBoss('barista');});
const ok=await waitFor(async()=>(await ev(()=>window.__BELLINGHAM.mode))==='combat','combat');
console.log('COMBAT', ok);
if(ok){ await ev(()=>window.__BELLINGHAM.instantWin()); await page.waitForTimeout(700); }
console.log('AFTER BOSS', await ev(()=>({stage:window.__BELLINGHAM.state.quest.stage,bosses:window.__BELLINGHAM.state.flags.bossesDefeated,truth:window.__BELLINGHAM.state.flags.truthRevealed})));
await ev(()=>{const g=window.__BELLINGHAM,f=g.state.flags;f.bossesDefeated=['barista','ferryman','hiker','mechanic','student','oldman','raincoat','mirror','mayor','future'];f.artifacts=['token','raincoat_button','mirror_shard','cassette'];f.mirrorDefeated=true;f.truthRevealed=true;f.futureDefeated=true;g.state.relationships.wren.met=true;g.state.relationships.wren.affinity=40;g.setMode('play');g.openEndingChoices();});
await page.waitForTimeout(500);
const opts=await ev(()=>[...document.querySelectorAll('#modal-actions button')].map(b=>({t:b.textContent,d:b.disabled})));
console.log('ENDINGS', JSON.stringify(opts));
await ev(()=>window.__BELLINGHAM.chooseEnding('escape'));
await page.waitForTimeout(9000);
console.log('ENDING CARD', await ev(()=>({endings:window.__BELLINGHAM.state.flags.endings,title:document.getElementById('modal-title').textContent,mode:window.__BELLINGHAM.mode})));
console.log('ERRORS', errors.length?errors.join('\n---\n'):'none');
await browser.close();

